def compute(vars):
    allowance_amount = -vars["v1"]
    receivables = vars["v2"]
    if receivables == 0:
        return None
    percentage = allowance_amount / receivables * 100
    return {
        "value": percentage,
        "trace": {
            "allowance_amount": allowance_amount,
            "receivables": receivables,
            "ratio": allowance_amount / receivables,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
